	}

	if len(trimmed) == 0 {
		return 0, errors.New("empty retry-after value")
	}

	if isDecimalInteger(trimmed) {
		seconds, err := strconv.ParseInt(trimmed, 10, 64)
		if err != nil {
			return 0, err
		}
		if seconds < 0 {
			return 0, errors.New("negative retry-after value")
		}
		const maxSeconds = 9223372036
		if seconds > maxSeconds {
			return 0, errors.New("retry-after value overflows duration")
		}
		d := time.Duration(seconds) * time.Second
		if d <= 0 {
			return 0, nil
		}
		return d, nil
	}

	t, err := http.ParseTime(trimmed)
	if err != nil {
		return 0, errors.New("invalid retry-after value")
	}

	d := t.Sub(now)
	if d <= 0 {
		return 0, nil
	}
	return d, nil
}

func isDecimalInteger(s string) bool {
	if len(s) == 0 {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

